			var val = this.data.meta[key];
			if (isArray(val)) {
				val = val.join(';');
			} else if (typeof val === 'object') {
				val = JSON.stringify(val);
			}
			data['meta[' + key + ']'] = val;
		}
		var n = this.data.weighted.length;
		for (var i = 0; i < n; i++) {
			var w = ((i + 1) / (n / 0.05)).toFixed(4);
			data['q[' + w + ']'] = this.data.weighted[i];
